// SELECT + alias + NULL (simulasi konsep dengan array JS)
const customers = [
  { id: 1, name: 'Ayu', city: 'Bandung', balance: 150000 },
  { id: 2, name: 'Bima', city: 'Jakarta', balance: null },
  { id: 3, name: 'Citra', city: 'Bandung', balance: 50000 }
];

// SELECT city, name AS customer_name, balance AS saldo
// Simulasi ekspresi: balance * 0.1 (mis. pajak/fee) dengan aturan NULL jadi 0
const result = customers
  .filter(c => c.city === 'Bandung') // analog WHERE city = 'Bandung'
  .map(c => ({
    customer_name: c.name, // alias
    saldo: c.balance,       // menampilkan NULL jika ada
    fee: (c.balance == null ? 0 : c.balance * 0.1) // NULL-handling
  }));

console.log('Hasil SELECT (simulasi):', result);

// WHERE operator simulasi: BETWEEN, IN, LIKE
const products = [
  { id: 1, title: 'Notebook A5', category: 'Stationery', price: 25000 },
  { id: 2, title: 'Pensil 2B', category: 'Stationery', price: 5000 },
  { id: 3, title: 'Mouse Wireless', category: 'Electronics', price: 85000 },
  { id: 4, title: 'Kabel USB-C', category: 'Electronics', price: 35000 }
];

const between = (x, a, b) => x >= a && x <= b;
const like = (text, pattern) => {
  // pola sederhana: '%abc%' contains, 'abc%' startsWith, '%abc' endsWith, 'abc' exact
  if (pattern.startsWith('%') && pattern.endsWith('%')) return text.includes(pattern.slice(1, -1));
  if (pattern.endsWith('%')) return text.startsWith(pattern.slice(0, -1));
  if (pattern.startsWith('%')) return text.endsWith(pattern.slice(1));
  return text === pattern;
};

// WHERE price BETWEEN 10000 AND 40000
const q1 = products.filter(p => between(p.price, 10000, 40000));

// WHERE category IN ('Stationery','Electronics') (semua cocok di contoh ini)
const allowedCategories = new Set(['Stationery', 'Electronics']);
const q2 = products.filter(p => allowedCategories.has(p.category));

// WHERE title LIKE '%USB%'
const q3 = products.filter(p => like(p.title, '%USB%'));

console.log('Q1 BETWEEN 10000-40000:', q1);
console.log('Q2 IN categories:', q2);
console.log('Q3 LIKE "%USB%":', q3);
